// Standardize Input: Ensure we have a clean array of objects
// Removes null values and flattens input

const items = $input.all().map(i => i.json);

// Determine source of data (body or direct)
const rawData = items.map(item => item.body || item);

const cleanData = rawData.map(item => {
    // Remove null keys to prevent overwriting existing data with nulls
    return Object.fromEntries(
        Object.entries(item).filter(([_, v]) => v !== null)
    );
});

return cleanData.map(item => ({ json: item }));

// --- CONFIGURATION ---
const CONFIG = {
  sheetName: $('Config').first().json.sheet_name,
  idColumn: $('Config').first().json.id_column_header,
};

// --- HELPERS ---
function columnToLetter(column) {
  let letter = '';
  let temp = column;
  while (temp >= 0) {
    letter = String.fromCharCode((temp % 26) + 65) + letter;
    temp = Math.floor(temp / 26) - 1;
  }
  return letter;
}

function generateUniqueId() {
  return `${Date.now()}${Math.floor(Math.random() * 1000000).toString(36)}`;
}

function sanitize(val) {
  if (val === null || val === undefined) return '';
  if (typeof val === 'object') return JSON.stringify(val);
  return val;
}

// --- INPUTS ---
const currentSheetRows = $('Get Current Sheet').all().map(i => i.json);
const incomingItems = $('Standardize Input').all().map(i => i.json);

// --- 1. INDEXING (Optimization: O(N)) ---
// We build Hash Maps for instant lookups
const idIndex = new Map();
const companyIndex = new Map();

// Capture Headers from the first row of sheet data
// Filter out n8n metadata like 'row_number'
const headers = Object.keys(currentSheetRows[0] || {}).filter(k => k !== 'row_number');
const headerMap = {};
headers.forEach((h, i) => headerMap[h] = i);

currentSheetRows.forEach(row => {
  // Primary Index: ID
  if (row[CONFIG.idColumn]) {
    idIndex.set(String(row[CONFIG.idColumn]), row);
  }

  // Secondary Index: Company + Doc ID
  if (row['COMPANY_ID'] && row['COMPANY_DOC_ID']) {
    const key = `${row['COMPANY_ID']}_${row['COMPANY_DOC_ID']}`.toLowerCase();
    companyIndex.set(key, row);
  }
});

// --- 2. PROCESSING ---
const batchUpdates = [];
const newRows = [];
const logs = [];

for (const item of incomingItems) {
  let match = null;
  let matchType = '';

  // Attempt Match A: ID
  if (item[CONFIG.idColumn]) {
    match = idIndex.get(String(item[CONFIG.idColumn]));
    matchType = 'ID';
  }

  // Attempt Match B: Composite Key
  if (!match && item['COMPANY_ID'] && item['COMPANY_DOC_ID']) {
    const key = `${item['COMPANY_ID']}_${item['COMPANY_DOC_ID']}`.toLowerCase();
    match = companyIndex.get(key);
    matchType = 'Composite';
  }

  // Attempt Match C: Hash (Optional fallback)
  // Add here if needed

  if (match) {
    // UPDATE EXISTING
    const rowNumber = match.row_number;
    let hasChanges = false;

    // Add timestamp to update
    item['TIMESTAMP'] = new Date().toISOString();

    for (const [key, newVal] of Object.entries(item)) {
      if (key === CONFIG.idColumn) continue; // Don't update ID
      if (headerMap[key] === undefined) continue; // Skip unknown columns

      const oldVal = String(sanitize(match[key]));
      const cleanNewVal = String(sanitize(newVal));

      if (oldVal !== cleanNewVal) {
        const colLetter = columnToLetter(headerMap[key]);
        batchUpdates.push({
          range: `${CONFIG.sheetName}!${colLetter}${rowNumber}`,
          values: [[sanitize(newVal)]]
        });
        hasChanges = true;
      }
    }
    if (hasChanges) logs.push(`Updated Row ${rowNumber} via ${matchType}`);
  } else {
    // CREATE NEW
    if (!item[CONFIG.idColumn]) {
        item[CONFIG.idColumn] = generateUniqueId();
    }
    item['TIMESTAMP'] = new Date().toISOString();

    // Map object to array based on header order
    const rowArray = headers.map(h => sanitize(item[h]));
    newRows.push(rowArray);
    logs.push(`Created new row with ID ${item[CONFIG.idColumn]}`);
  }
}

return {
  json: {
    stats: {
      updates: batchUpdates.length,
      creates: newRows.length,
      logs
    },
    hasUpdates: batchUpdates.length > 0,
    hasCreates: newRows.length > 0,
    updatePayload: batchUpdates,
    createPayload: newRows.length > 0 ? [
        {
            range: CONFIG.sheetName,
            values: newRows
        }
    ] : []
  }
};

// 1. Normalize Input
// Handles Webhook body, Subworkflow items, or Manual input uniformally

let items = [];

// Check if input is an array or object and normalize
if (Array.isArray($input.all())) {
  items = $input.all().map(i => i.json);
  // If webhook body is wrapped in 'body' key
  if (items.length === 1 && items[0].body) {
    items = Array.isArray(items[0].body) ? items[0].body : [items[0].body];
  }
}

// 2. Sanitize & Prepare
const cleanItems = items.map(item => {
  // Remove nulls and undefined
  const clean = Object.fromEntries(
    Object.entries(item).filter(([_, v]) => v != null)
  );

  // Ensure ID is string if exists
  if (clean.ID) clean.ID = String(clean.ID);

  // Add processing timestamp
  clean.TIMESTAMP = new Date().toISOString();

  // Tag for processing
  return clean;
});

return cleanItems.map(item => ({ json: item }));

// CONFIGURATION
const CONFIG = $('CONFIG').first().json;
const ID_COL = CONFIG.ID_COLUMN;
const SHEET_NAME = CONFIG.SHEET_NAME;

// HELPER: Column Index to Letter (0 -> A, 26 -> AA)
function columnToLetter(column) {
  let letter = '';
  let temp = column;
  while (temp >= 0) {
    letter = String.fromCharCode((temp % 26) + 65) + letter;
    temp = Math.floor(temp / 26) - 1;
  }
  return letter;
}

// HELPER: Generate ID
function generateUniqueId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

// 1. INDEX SHEET DATA
const sheetRows = $('Get Current Sheet State').all().map(i => i.json);
const headers = Object.keys(sheetRows[0] || {}).filter(k => k !== 'row_number');

// Build Header Map (Key -> Column Index)
const headerMap = {};
headers.forEach((h, i) => headerMap[h] = i);

// Build Row Index (ID -> Row Data)
const rowIndex = new Map();
// Build Secondary Index (CompanyID+DocID -> Row Data) for matching
const secondaryIndex = new Map();

sheetRows.forEach(row => {
  if (row[ID_COL]) rowIndex.set(String(row[ID_COL]), row);

  // Secondary matching logic based on your previous workflow
  if (row.COMPANY_ID && row.COMPANY_DOC_ID) {
    secondaryIndex.set(`${row.COMPANY_ID}_${row.COMPANY_DOC_ID}`, row);
  }
});

// 2. PROCESS INPUTS
const updates = [];
const appends = [];
const inputs = $('Normalize Input').all().map(i => i.json);
const logs = [];

for (const item of inputs) {
  let match = null;
  let matchType = 'none';

  // Try ID Match
  if (item[ID_COL] && rowIndex.has(String(item[ID_COL]))) {
    match = rowIndex.get(String(item[ID_COL]));
    matchType = 'id';
  }
  // Try Secondary Match
  else if (item.COMPANY_ID && item.COMPANY_DOC_ID) {
    const key = `${item.COMPANY_ID}_${item.COMPANY_DOC_ID}`;
    if (secondaryIndex.has(key)) {
      match = secondaryIndex.get(key);
      matchType = 'secondary';
    }
  }
  // Try Hash Match (Optional based on previous code)
  // ...

  if (match) {
    // --- UPDATE LOGIC ---
    const rowNum = match.row_number;

    // Check for actual changes
    Object.keys(item).forEach(key => {
      if (key === ID_COL) return; // Don't update ID
      if (headerMap[key] === undefined) return; // Skip unknown columns

      const oldVal = match[key] == null ? '' : String(match[key]);
      const newVal = item[key] == null ? '' : String(item[key]);

      if (oldVal !== newVal) {
        const colLetter = columnToLetter(headerMap[key]);
        updates.push({
          range: `${SHEET_NAME}!${colLetter}${rowNum}`,
          values: [[item[key]]]
        });
      }
    });
  } else {
    // --- CREATE LOGIC ---
    // Generate ID if missing
    if (!item[ID_COL]) item[ID_COL] = generateUniqueId();

    // Map item to full row array based on headers
    const newRow = headers.map(h => item[h] || '');
    appends.push(newRow);
  }
}

return {
  json: {
    hasUpdates: updates.length > 0,
    hasAppends: appends.length > 0,
    updateCount: updates.length,
    appendCount: appends.length,
    batchUpdates: updates,
    appendRows: appends
  }
};

// =============================================================================
// PHASE 1: NORMALIZE INPUT
// Unifies all entry points into consistent array format
// =============================================================================

const CONFIG = {
  ID_COLUMN: 'ID',
  MATCHING_PRIMARY: ['COMPANY_ID', 'COMPANY_DOC_ID'],
  MATCHING_SECONDARY: 'HASH'
};

function generateId() {
  return `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

function generateRequestId() {
  return `req_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
}

function cleanObject(obj) {
  const cleaned = {};
  for (const [key, value] of Object.entries(obj)) {
    if (value !== null && value !== undefined) {
      cleaned[key] = value;
    }
  }
  return cleaned;
}

function getLockKey(item) {
  // Priority: ID > COMPANY_ID+COMPANY_DOC_ID > HASH
  if (item[CONFIG.ID_COLUMN]) {
    return `id:${item[CONFIG.ID_COLUMN]}`;
  }

  const hasCompanyKeys = CONFIG.MATCHING_PRIMARY.every(k => 
    item[k] && String(item[k]).toLowerCase() !== 'unknown'
  );
  if (hasCompanyKeys) {
    return `company:${CONFIG.MATCHING_PRIMARY.map(k => item[k]).join('|')}`;
  }

  if (item[CONFIG.MATCHING_SECONDARY]) {
    return `hash:${item[CONFIG.MATCHING_SECONDARY]}`;
  }

  // New record with no identifiers - generate temp key
  return `temp:${generateId()}`;
}

// --- Main Logic ---
const startTime = Date.now();
const requestId = generateRequestId();
const allInputs = $input.all();
const items = [];
const lockKeys = [];
const errors = [];

for (const input of allInputs) {
  let data = input.json;

  // Handle webhook body wrapper
  if (data.body && typeof data.body === 'object') {
    data = data.body;
  }

  // Handle array in body
  const dataArray = Array.isArray(data) ? data : [data];

  for (const item of dataArray) {
    if (!item || typeof item !== 'object') {
      errors.push('Invalid item: not an object');
      continue;
    }

    const cleaned = cleanObject(item);

    // Add timestamp if missing
    if (!cleaned.TIMESTAMP) {
      cleaned.TIMESTAMP = new Date().toISOString();
    }

    // Generate lock key
    const lockKey = getLockKey(cleaned);
    cleaned._lockKey = lockKey;
    cleaned._isNew = !cleaned[CONFIG.ID_COLUMN];

    // Generate ID for new records
    if (cleaned._isNew) {
      cleaned._generatedId = generateId();
    }

    items.push(cleaned);
    lockKeys.push(lockKey);
  }
}

if (errors.length > 0 && items.length === 0) {
  throw new Error(`Validation failed: ${errors.join('; ')}`);
}

// Detect entry point
const entryPoint = $input.first().json.headers ? 'webhook' : 
                   $input.first().json.body ? 'webhook' : 'subworkflow';

return [{
  json: {
    requestId,
    entryPoint,
    items,
    lockKeys: [...new Set(lockKeys)], // Dedupe
    itemCount: items.length,
    hasNewRecords: items.some(i => i._isNew),
    timing: { normalizeMs: Date.now() - startTime },
    errors: errors.length > 0 ? errors : undefined
  }
}];

// =============================================================================
// PHASE 2: ACQUIRE LOCKS
// Simple in-memory lock tracking (replace with Redis/DB for production)
// =============================================================================

const input = $input.first().json;
const lockKeys = input.lockKeys || [];
const acquiredLocks = [];

// In production, this would call an external lock service
// For now, we just track what we need to lock
for (const key of lockKeys) {
  acquiredLocks.push({
    key,
    acquiredAt: new Date().toISOString()
  });
}

return [{
  json: {
    ...input,
    locks: {
      keys: acquiredLocks,
      count: acquiredLocks.length,
      allAcquired: true
    },
    timing: {
      ...input.timing,
      lockMs: Date.now() - new Date(input.timing?.normalizeMs ? Date.now() - input.timing.normalizeMs : Date.now()).getTime()
    }
  }
}];

// =============================================================================
// PHASE 4: COMPUTE CHANGES
// Diff current state vs desired state, prepare operations
// =============================================================================

const CONFIG = {
  SHEET_NAME: 'מסמכים נכנסים',
  ID_COLUMN: 'ID',
  MATCHING_PRIMARY: ['COMPANY_ID', 'COMPANY_DOC_ID'],
  MATCHING_SECONDARY: 'HASH',
  MAX_BATCH_SIZE: 500
};

// --- Helper Functions ---
function columnToLetter(col) {
  let letter = '';
  let temp = col;
  while (temp >= 0) {
    letter = String.fromCharCode((temp % 26) + 65) + letter;
    temp = Math.floor(temp / 26) - 1;
  }
  return letter;
}

function sanitize(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return value;
}

function matchByFields(item, index, fields) {
  const hasAll = fields.every(f => {
    const v = item[f];
    return v && String(v).toLowerCase() !== 'unknown';
  });
  if (!hasAll) return null;

  for (const [key, row] of index.entries()) {
    const matches = fields.every(f => 
      String(item[f] || '').toLowerCase() === String(row[f] || '').toLowerCase()
    );
    if (matches) return { key, row };
  }
  return null;
}

// --- Get Input Data ---
const inputData = $('2. Acquire Locks').first().json;
const sheetRows = $('3. Fetch Sheet Data').all().map(i => i.json);
const items = inputData.items || [];

const startTime = Date.now();

// --- Build Indexes ---
if (!sheetRows || sheetRows.length === 0) {
  throw new Error('Sheet is empty or inaccessible');
}

const headers = Object.keys(sheetRows[0]).filter(k => k !== 'row_number');
const headerMap = new Map(headers.map((h, i) => [h, i]));

const byId = new Map();
const byCompany = new Map();
const byHash = new Map();

for (const row of sheetRows) {
  const id = row[CONFIG.ID_COLUMN];
  if (id) byId.set(String(id), row);

  const companyKey = CONFIG.MATCHING_PRIMARY.map(k => row[k] || '').join('|').toLowerCase();
  if (companyKey && !companyKey.includes('unknown')) {
    byCompany.set(companyKey, row);
  }

  const hash = row[CONFIG.MATCHING_SECONDARY];
  if (hash) byHash.set(String(hash).toLowerCase(), row);
}

// --- Process Items ---
const updates = [];
const creates = [];
const skipped = [];
const errors = [];

let totalCellChanges = 0;

for (const item of items) {
  let foundRow = null;
  let matchMethod = null;

  // Try to find existing row
  const itemId = item[CONFIG.ID_COLUMN];
  if (itemId) {
    foundRow = byId.get(String(itemId));
    matchMethod = 'id';
  }

  if (!foundRow) {
    const companyKey = CONFIG.MATCHING_PRIMARY.map(k => item[k] || '').join('|').toLowerCase();
    if (companyKey && !companyKey.includes('unknown') && byCompany.has(companyKey)) {
      foundRow = byCompany.get(companyKey);
      matchMethod = 'company';
    }
  }

  if (!foundRow && item[CONFIG.MATCHING_SECONDARY]) {
    const hash = String(item[CONFIG.MATCHING_SECONDARY]).toLowerCase();
    if (byHash.has(hash)) {
      foundRow = byHash.get(hash);
      matchMethod = 'hash';
    }
  }

  // --- UPDATE existing row ---
  if (foundRow) {
    const rowNumber = foundRow.row_number;
    if (!rowNumber) {
      errors.push({ item, error: 'Missing row_number' });
      continue;
    }

    const changes = [];
    for (const [field, newValue] of Object.entries(item)) {
      // Skip internal fields
      if (field.startsWith('_')) continue;
      if (field === CONFIG.ID_COLUMN) continue;

      const colIndex = headerMap.get(field);
      if (colIndex === undefined) continue;

      const oldValue = sanitize(foundRow[field]);
      const newSanitized = sanitize(newValue);

      if (String(oldValue) === String(newSanitized)) continue;

      const cellLetter = columnToLetter(colIndex);
      changes.push({
        field,
        oldValue,
        newValue: newSanitized,
        cell: `${cellLetter}${rowNumber}`,
        range: `${CONFIG.SHEET_NAME}!${cellLetter}${rowNumber}`
      });
    }

    if (changes.length === 0) {
      skipped.push({ 
        id: foundRow[CONFIG.ID_COLUMN], 
        reason: 'no_changes',
        matchMethod 
      });
    } else {
      updates.push({
        rowNumber,
        id: foundRow[CONFIG.ID_COLUMN],
        matchMethod,
        changes
      });
      totalCellChanges += changes.length;
    }
  }
  // --- CREATE new row ---
  else {
    const newId = item._generatedId || `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const rowValues = headers.map(h => {
      if (h === CONFIG.ID_COLUMN) return newId;
      return sanitize(item[h]);
    });

    creates.push({
      generatedId: newId,
      values: rowValues,
      originalItem: item
    });
  }
}

// --- Validate Batch Size ---
const totalOps = updates.reduce((sum, u) => sum + u.changes.length, 0) + creates.length;
if (totalOps > CONFIG.MAX_BATCH_SIZE) {
  throw new Error(`Batch too large: ${totalOps} operations exceeds limit of ${CONFIG.MAX_BATCH_SIZE}`);
}

// --- Prepare API Payloads ---
const batchUpdateData = [];
for (const update of updates) {
  for (const change of update.changes) {
    batchUpdateData.push({
      range: change.range,
      values: [[change.newValue]]
    });
  }
}

const appendData = creates.map(c => c.values);

return [{
  json: {
    ...inputData,
    computation: {
      updates,
      creates,
      skipped,
      errors,
      stats: {
        toUpdate: updates.length,
        toCreate: creates.length,
        toSkip: skipped.length,
        cellChanges: totalCellChanges,
        errors: errors.length
      }
    },
    operations: {
      hasUpdates: batchUpdateData.length > 0,
      hasCreates: appendData.length > 0,
      batchUpdatePayload: {
        valueInputOption: 'RAW',
        data: batchUpdateData
      },
      appendPayload: {
        range: CONFIG.SHEET_NAME,
        values: appendData
      }
    },
    sheetMeta: {
      headers,
      rowCount: sheetRows.length,
      indexedById: byId.size,
      indexedByCompany: byCompany.size,
      indexedByHash: byHash.size
    },
    timing: {
      ...inputData.timing,
      computeMs: Date.now() - startTime
    }
  }
}];

// =============================================================================
// PHASE 6: RELEASE LOCKS
// Release all acquired locks
// =============================================================================

const computeData = $('4. Compute Changes').first().json;
const locks = computeData.locks?.keys || [];

// In production, this would call the lock service to release
// For now, we just track that we're releasing them

const releasedLocks = locks.map(lock => ({
  ...lock,
  releasedAt: new Date().toISOString()
}));

return [{
  json: {
    ...computeData,
    locks: {
      ...computeData.locks,
      released: true,
      releasedAt: new Date().toISOString()
    }
  }
}];

// =============================================================================
// PHASE 7: FORMAT RESPONSE
// Create structured response for all entry points
// =============================================================================

const data = $input.first().json;
const comp = data.computation || {};
const stats = comp.stats || {};
const timing = data.timing || {};

const totalTimeMs = Object.values(timing).reduce((a, b) => a + (typeof b === 'number' ? b : 0), 0);

const response = {
  success: true,
  requestId: data.requestId,
  summary: {
    processed: data.itemCount || 0,
    updated: stats.toUpdate || 0,
    created: stats.toCreate || 0,
    skipped: stats.toSkip || 0,
    cellsModified: stats.cellChanges || 0
  },
  details: {
    updates: (comp.updates || []).map(u => ({
      id: u.id,
      matchMethod: u.matchMethod,
      fieldsChanged: u.changes.map(c => c.field)
    })),
    creates: (comp.creates || []).map(c => ({
      id: c.generatedId
    })),
    skipped: comp.skipped || []
  },
  timing: {
    ...timing,
    totalMs: totalTimeMs
  },
  meta: {
    entryPoint: data.entryPoint,
    timestamp: new Date().toISOString()
  }
};

// Add errors if any
if (comp.errors && comp.errors.length > 0) {
  response.errors = comp.errors;
}

return [{ json: response }];

// =============================================================================
// ERROR HANDLER: Release locks and format error response
// =============================================================================

const error = $input.first().json;
let computeData = {};

try {
  computeData = $('4. Compute Changes').first()?.json || {};
} catch (e) {
  try {
    computeData = $('2. Acquire Locks').first()?.json || {};
  } catch (e2) {
    computeData = $('1. Normalize Input').first()?.json || {};
  }
}

const response = {
  success: false,
  requestId: computeData.requestId || 'unknown',
  error: {
    message: error.message || 'Unknown error',
    code: error.code || 'INTERNAL_ERROR'
  },
  meta: {
    entryPoint: computeData.entryPoint || 'unknown',
    timestamp: new Date().toISOString(),
    locksReleased: true
  }
};

return [{ json: response }];

// ============================================================================
// GOOGLE SHEETS UPSERT - COMPLETE UNIFIED PROCESSOR
// ============================================================================
// Handles: Single items, Batch items, Updates, Creates (Upserts)
// Entry: Webhook, Sub-workflow, or Manual trigger
// ============================================================================

// =========================== CONFIGURATION ===================================
const CONFIG = {
  // Google Sheets
  spreadsheetId: '1Wu3hyF_4TvfU41xCGaINtJD81Or0wBSwD1djp4tVJEo',
  sheetName: 'מסמכים נכנסים',
  sheetGid: 542119184,

  // Column settings
  idColumn: 'ID',
  matchingPrimary: ['COMPANY_ID', 'COMPANY_DOC_ID'],
  matchingSecondary: 'HASH',

  // Limits
  maxBatchSize: 500,
  maxRetries: 3,
  retryDelayMs: 1000,

  // Behavior
  strictMode: false,        // If true, stop on first error
  skipUnchanged: true,      // Skip cells with same value
  generateTimestamp: true,  // Auto-update TIMESTAMP field

  // Schema - all allowed columns
  schema: [
    'ID', 'NAME', 'COMPANY_ID', 'SHORT_DOC_ID', 'TYPE', 'STATUS',
    'COMPANY_DOC_ID', 'LINK', 'PURCHASE_ID', 'SHIPMENT_DOC_ID',
    'LINKED_BS', 'BS_LINE_DATE', 'BS_LINE_AMOUNT', 'SOURCE_TYPE',
    'SOURCE_ID', 'SOURCE_LINK', 'SIZE', 'HASH', 'TIMESTAMP',
    'COMPANY_NAME', 'REQUIRED_ACTION', 'BS_EXTRACTED_LINES',
    'TOTAL_AMOUNT', 'BS_EXTRACTION_VERIFIED', 'BS_LINE_NOTE',
    'FROM_OFFICE', 'FROM_OFFICE_CHECK', 'BS_LINK_DOCUMENTS_COMPLETED',
    'SEARCH_IN_DRIVE_COMPLETED', 'PURCHASE_ID_COMPLETED',
    'SHIPMENT_ID_COMPLETED', 'COMPANY_NAME_COMPLETED',
    'API_TOOLS_ID_COMPLETED', 'API_TOOLS_ID', 'EMPTY',
    'BS_EXTRACTED_LINES_COMPLETED', 'BS_EXTRACTION_USE_CACHE',
    'EX_INVOICE_ID', 'INVOICE_ID_COMPLETED', 'EX_IS_BS_COMPLETED',
    'EX_IS_BS', 'FIGURE_TYPE_COMPLETED', 'DOUBLE_LINE_CONTEXT',
    'FIGURE_COMPANY_COMPLETED'
  ]
};

// =========================== UTILITIES =======================================

const utils = {
  // Generate unique ID
  generateId() {
    const ts = Date.now().toString(36);
    const rand = Math.random().toString(36).substring(2, 10);
    return `${ts}${rand}`;
  },

  // Convert column index to letter (0 = A, 26 = AA)
  columnToLetter(index) {
    let letter = '';
    let temp = index;
    while (temp >= 0) {
      letter = String.fromCharCode((temp % 26) + 65) + letter;
      temp = Math.floor(temp / 26) - 1;
    }
    return letter;
  },

  // Sanitize value for Sheets API
  sanitize(value) {
    if (value === null || value === undefined) return '';
    if (typeof value === 'object') return JSON.stringify(value);
    return value;
  },

  // Clean object - remove nulls/undefined
  cleanObject(obj) {
    return Object.fromEntries(
      Object.entries(obj).filter(([_, v]) => v !== null && v !== undefined)
    );
  },

  // Sleep helper for retries
  sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  },

  // Create composite key for matching
  compositeKey(obj, fields) {
    return fields.map(f => String(obj[f] || '').toLowerCase().trim()).join('|');
  },

  // Check if value is empty/unknown
  isEmpty(value) {
    return value === undefined || value === null || value === '' || 
           String(value).toLowerCase() === 'unknown';
  }
};

// =========================== HTTP CLIENT =====================================

async function sheetsRequest(endpoint, method = 'GET', body = null, retryCount = 0) {
  const baseUrl = `https://sheets.googleapis.com/v4/spreadsheets/${CONFIG.spreadsheetId}`;
  const url = `${baseUrl}${endpoint}`;

  const options = {
    method,
    headers: { 'Content-Type': 'application/json' },
    returnFullResponse: true
  };

  if (body) {
    options.body = JSON.stringify(body);
  }

  try {
    // Use n8n's built-in HTTP helper with OAuth
    const response = await this.helpers.httpRequestWithAuthentication.call(
      this,
      'googleSheetsOAuth2Api',
      { url, method, body, headers: { 'Content-Type': 'application/json' } }
    );
    return { success: true, data: response };
  } catch (error) {
    // Retry on 429 or 5xx
    const status = error.statusCode || error.response?.status;
    if ((status === 429 || status >= 500) && retryCount < CONFIG.maxRetries) {
      const delay = CONFIG.retryDelayMs * Math.pow(2, retryCount);
      console.log(`Retry ${retryCount + 1}/${CONFIG.maxRetries} after ${delay}ms...`);
      await utils.sleep(delay);
      return sheetsRequest.call(this, endpoint, method, body, retryCount + 1);
    }
    return { success: false, error: error.message, status };
  }
}

// =========================== PHASE 1: NORMALIZE ==============================

function normalizeInput(inputItems) {
  const requestId = utils.generateId();
  const startTime = Date.now();

  // Collect all items from input
  let items = [];

  for (const input of inputItems) {
    const data = input.json?.body || input.json;
    if (Array.isArray(data)) {
      items.push(...data);
    } else if (data && typeof data === 'object') {
      items.push(data);
    }
  }

  // Clean and validate each item
  const cleaned = items.map((item, idx) => {
    const clean = utils.cleanObject(item);

    // Add timestamp if configured
    if (CONFIG.generateTimestamp && !clean.TIMESTAMP) {
      clean.TIMESTAMP = new Date().toISOString();
    }

    // Generate temp ID for tracking new records
    clean._tempId = clean[CONFIG.idColumn] || `new_${idx}_${utils.generateId()}`;
    clean._isNew = !clean[CONFIG.idColumn];

    return clean;
  });

  return {
    items: cleaned,
    itemCount: cleaned.length,
    hasNewRecords: cleaned.some(i => i._isNew),
    requestId,
    timing: { normalizeMs: Date.now() - startTime }
  };
}

// =========================== PHASE 2: FETCH STATE ============================

async function fetchSheetState() {
  const startTime = Date.now();

  // Fetch all data from sheet
  const endpoint = `/values/${encodeURIComponent(CONFIG.sheetName)}?valueRenderOption=UNFORMATTED_VALUE`;
  const response = await sheetsRequest.call(this, endpoint);

  if (!response.success) {
    throw new Error(`Failed to fetch sheet data: ${response.error}`);
  }

  const rows = response.data.values || [];
  if (rows.length === 0) {
    throw new Error('Sheet is empty - no headers found');
  }

  // First row is headers
  const headers = rows[0];
  const headerMap = new Map(headers.map((h, i) => [h, i]));

  // Validate ID column exists
  if (!headerMap.has(CONFIG.idColumn)) {
    throw new Error(`ID column "${CONFIG.idColumn}" not found in sheet`);
  }

  // Build indexes for fast lookup
  const byId = new Map();
  const byCompanyKey = new Map();
  const byHash = new Map();

  for (let rowNum = 1; rowNum < rows.length; rowNum++) {
    const row = rows[rowNum];
    const rowObj = { _rowNumber: rowNum + 1 }; // 1-indexed for Sheets

    headers.forEach((header, colIdx) => {
      rowObj[header] = row[colIdx];
    });

    // Index by ID
    const id = rowObj[CONFIG.idColumn];
    if (id !== undefined && id !== null && id !== '') {
      byId.set(String(id), rowObj);
    }

    // Index by company composite key
    const companyKey = utils.compositeKey(rowObj, CONFIG.matchingPrimary);
    if (companyKey && !CONFIG.matchingPrimary.some(f => utils.isEmpty(rowObj[f]))) {
      byCompanyKey.set(companyKey, rowObj);
    }

    // Index by hash
    const hash = rowObj[CONFIG.matchingSecondary];
    if (hash && !utils.isEmpty(hash)) {
      byHash.set(String(hash).toLowerCase(), rowObj);
    }
  }

  return {
    headers,
    headerMap,
    byId,
    byCompanyKey,
    byHash,
    totalRows: rows.length - 1,
    timing: { fetchMs: Date.now() - startTime }
  };
}

// =========================== PHASE 3: COMPUTE CHANGES ========================

function computeChanges(items, state) {
  const startTime = Date.now();
  const { headers, headerMap, byId, byCompanyKey, byHash } = state;

  const updates = [];
  const creates = [];
  const skipped = [];
  const errors = [];
  const warnings = [];

  const processedIds = new Set();

  for (const item of items) {
    let existingRow = null;
    let matchMethod = null;

    // Try to find existing row
    const itemId = item[CONFIG.idColumn];

    if (itemId && !utils.isEmpty(itemId)) {
      // Direct ID lookup
      existingRow = byId.get(String(itemId));
      matchMethod = 'id';

      if (processedIds.has(String(itemId))) {
        warnings.push(`Duplicate ID "${itemId}" in batch - using latest`);
      }
      processedIds.add(String(itemId));
    } else {
      // Try company key match
      const companyKey = utils.compositeKey(item, CONFIG.matchingPrimary);
      if (!CONFIG.matchingPrimary.some(f => utils.isEmpty(item[f]))) {
        existingRow = byCompanyKey.get(companyKey);
        if (existingRow) matchMethod = 'company';
      }

      // Try hash match
      if (!existingRow && item[CONFIG.matchingSecondary]) {
        const hashKey = String(item[CONFIG.matchingSecondary]).toLowerCase();
        existingRow = byHash.get(hashKey);
        if (existingRow) matchMethod = 'hash';
      }
    }

    if (existingRow) {
      // === UPDATE existing row ===
      const rowNumber = existingRow._rowNumber;
      const changes = [];

      for (const [field, newValue] of Object.entries(item)) {
        // Skip internal fields
        if (field.startsWith('_')) continue;
        if (field === CONFIG.idColumn) continue;

        // Check column exists
        const colIndex = headerMap.get(field);
        if (colIndex === undefined) {
          if (CONFIG.strictMode) {
            errors.push(`Column "${field}" not found for row ${rowNumber}`);
            break;
          }
          warnings.push(`Column "${field}" not found - skipping`);
          continue;
        }

        const oldValue = utils.sanitize(existingRow[field]);
        const sanitizedNew = utils.sanitize(newValue);

        // Skip if unchanged
        if (CONFIG.skipUnchanged && String(oldValue) === String(sanitizedNew)) {
          continue;
        }

        const cellRef = `${utils.columnToLetter(colIndex)}${rowNumber}`;
        changes.push({
          column: field,
          colIndex,
          cell: cellRef,
          oldValue,
          newValue: sanitizedNew
        });
      }

      if (changes.length > 0) {
        updates.push({
          rowNumber,
          id: existingRow[CONFIG.idColumn] || item._tempId,
          matchMethod,
          changes
        });
      } else {
        skipped.push({
          id: existingRow[CONFIG.idColumn] || item._tempId,
          reason: 'no_changes'
        });
      }
    } else {
      // === CREATE new row ===
      const newId = utils.generateId();
      const rowValues = headers.map(header => {
        if (header === CONFIG.idColumn) return newId;
        return utils.sanitize(item[header]);
      });

      creates.push({
        tempId: item._tempId,
        generatedId: newId,
        values: rowValues
      });
    }

    if (CONFIG.strictMode && errors.length > 0) break;
  }

  // Calculate stats
  const stats = {
    toUpdate: updates.length,
    toCreate: creates.length,
    toSkip: skipped.length,
    cellChanges: updates.reduce((sum, u) => sum + u.changes.length, 0),
    matchedById: updates.filter(u => u.matchMethod === 'id').length,
    matchedByCompany: updates.filter(u => u.matchMethod === 'company').length,
    matchedByHash: updates.filter(u => u.matchMethod === 'hash').length,
    errors: errors.length,
    warnings: warnings.length
  };

  return {
    updates,
    creates,
    skipped,
    errors,
    warnings,
    stats,
    timing: { computeMs: Date.now() - startTime }
  };
}

// =========================== PHASE 4: APPLY CHANGES ==========================

async function applyChanges(changes) {
  const startTime = Date.now();
  const results = { updates: null, creates: null };

  // Validate batch size
  const totalOps = changes.updates.length + changes.creates.length;
  if (totalOps > CONFIG.maxBatchSize) {
    throw new Error(`Total operations (${totalOps}) exceeds limit (${CONFIG.maxBatchSize})`);
  }

  // === Apply Updates ===
  if (changes.updates.length > 0) {
    const batchData = [];

    for (const update of changes.updates) {
      for (const change of update.changes) {
        batchData.push({
          range: `${CONFIG.sheetName}!${change.cell}`,
          values: [[change.newValue]]
        });
      }
    }

    const updateResponse = await sheetsRequest.call(
      this,
      '/values:batchUpdate',
      'POST',
      {
        valueInputOption: 'RAW',
        data: batchData
      }
    );

    if (!updateResponse.success) {
      throw new Error(`Batch update failed: ${updateResponse.error}`);
    }

    results.updates = {
      success: true,
      cellsUpdated: batchData.length,
      response: updateResponse.data
    };
  }

  // === Apply Creates (Appends) ===
  if (changes.creates.length > 0) {
    const appendResponse = await sheetsRequest.call(
      this,
      `/values/${encodeURIComponent(CONFIG.sheetName)}:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS`,
      'POST',
      {
        values: changes.creates.map(c => c.values)
      }
    );

    if (!appendResponse.success) {
      throw new Error(`Append failed: ${appendResponse.error}`);
    }

    results.creates = {
      success: true,
      rowsCreated: changes.creates.length,
      response: appendResponse.data
    };
  }

  return {
    results,
    timing: { applyMs: Date.now() - startTime }
  };
}

// =========================== MAIN EXECUTION ==================================

async function main() {
  const totalStartTime = Date.now();
  const timing = {};

  try {
    // PHASE 1: Normalize input
    console.log('Phase 1: Normalizing input...');
    const normalized = normalizeInput($input.all());
    Object.assign(timing, normalized.timing);

    if (normalized.itemCount === 0) {
      return [{
        json: {
          success: true,
          message: 'No items to process',
          requestId: normalized.requestId,
          summary: { updated: 0, created: 0, skipped: 0 }
        }
      }];
    }

    console.log(`Processing ${normalized.itemCount} item(s)...`);

    // PHASE 2: Fetch current state
    console.log('Phase 2: Fetching sheet state...');
    const state = await fetchSheetState.call(this);
    Object.assign(timing, state.timing);
    console.log(`Indexed ${state.totalRows} existing rows`);

    // PHASE 3: Compute changes
    console.log('Phase 3: Computing changes...');
    const changes = computeChanges(normalized.items, state);
    Object.assign(timing, changes.timing);

    // Check for errors in strict mode
    if (changes.errors.length > 0 && CONFIG.strictMode) {
      throw new Error(`Validation errors:\n${changes.errors.join('\n')}`);
    }

    console.log(`Updates: ${changes.stats.toUpdate}, Creates: ${changes.stats.toCreate}, Skipped: ${changes.stats.toSkip}`);

    // PHASE 4: Apply changes
    if (changes.stats.toUpdate > 0 || changes.stats.toCreate > 0) {
      console.log('Phase 4: Applying changes...');
      const applied = await applyChanges.call(this, changes);
      Object.assign(timing, applied.timing);
    }

    // Calculate total timing
    timing.totalMs = Date.now() - totalStartTime;

    // Build response
    const response = {
      success: true,
      requestId: normalized.requestId,
      summary: {
        processed: normalized.itemCount,
        updated: changes.stats.toUpdate,
        created: changes.stats.toCreate,
        skipped: changes.stats.toSkip,
        cellsModified: changes.stats.cellChanges
      },
      matching: {
        byId: changes.stats.matchedById,
        byCompanyKey: changes.stats.matchedByCompany,
        byHash: changes.stats.matchedByHash
      },
      details: {
        updates: changes.updates.map(u => ({
          id: u.id,
          row: u.rowNumber,
          matchedBy: u.matchMethod,
          fieldsChanged: u.changes.map(c => c.column)
        })),
        creates: changes.creates.map(c => ({
          tempId: c.tempId,
          assignedId: c.generatedId
        })),
        skipped: changes.skipped
      },
      timing,
      warnings: changes.warnings.length > 0 ? changes.warnings : undefined,
      errors: changes.errors.length > 0 ? changes.errors : undefined
    };

    console.log('\n=== COMPLETE ===');
    console.log(`Total time: ${timing.totalMs}ms`);
    console.log(`Updated: ${changes.stats.toUpdate}, Created: ${changes.stats.toCreate}`);

    return [{ json: response }];

  } catch (error) {
    console.error('FATAL ERROR:', error.message);

    return [{
      json: {
        success: false,
        error: error.message,
        errorType: error.name,
        timing: { ...timing, totalMs: Date.now() - totalStartTime }
      }
    }];
  }
}

// Execute
return main.call(this);
